import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);

/** Writes a small playable H.264 + AAC video generated by ffmpeg itself. */
export async function generateTestVideo(
  path: string,
  seconds = 2,
): Promise<void> {
  await execFileAsync('ffmpeg', [
    '-y',
    '-v',
    'error',
    '-f',
    'lavfi',
    '-i',
    `testsrc=duration=${seconds}:size=320x240:rate=15`,
    '-f',
    'lavfi',
    '-i',
    `sine=frequency=440:duration=${seconds}`,
    '-c:v',
    'libx264',
    '-pix_fmt',
    'yuv420p',
    '-c:a',
    'aac',
    '-shortest',
    path,
  ]);
}

/** Writes an audio-only file: valid media, but without a video stream. */
export async function generateTestAudio(path: string): Promise<void> {
  await execFileAsync('ffmpeg', [
    '-y',
    '-v',
    'error',
    '-f',
    'lavfi',
    '-i',
    'sine=frequency=440:duration=1',
    path,
  ]);
}
